fn choose_num(x: i8, y: i8) -> i8 {
    if x > y {
        return -1;
    }
    // Find the largest even number ≤ y
    let candidate = if y % 2 == 0 { y } else { y - 1 };
    // Check that this even number is still within [x, y]
    if candidate < x {
        -1
    } else {
        candidate
    }
}

